begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated,anon,service_role;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('70000000-0000-4000-8000-000000000001','content-owner@test.example','{"nome":"Dono Editorial","tipo":"fornecedor","empresa":"Empresa Editorial","cnpj":"11222333000181","telefone":"11999999999","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}'),
('70000000-0000-4000-8000-000000000002','content-editor@test.example','{"nome":"Editor Conteúdo","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}'),
('70000000-0000-4000-8000-000000000003','content-other@test.example','{"nome":"Outro Conteúdo","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}');
insert into public.user_roles(user_id,role) values('70000000-0000-4000-8000-000000000002','editor'),('70000000-0000-4000-8000-000000000003','comercial');
select set_config('test.sid',(select id::text from public.fornecedores where dono_id='70000000-0000-4000-8000-000000000001'),true);
update public.fornecedores set status='publicado',slug='empresa-editorial',teste_inicio=now(),teste_fim=now()+interval '90 days' where id=current_setting('test.sid')::uuid;
select set_config('test.cat',(select id::text from public.categorias where ativa limit 1),true);
select set_config('test.payload',jsonb_build_object('titulo','Planejamento editorial de teste','resumo','Resumo para validação editorial','corpo','[{"tipo":"paragrafo","texto":"Uma matéria de teste com mais de dez palavras para validar todo o processo editorial do fornecedor."}]'::jsonb,'categoria_id',current_setting('test.cat'))::text,true);
set local role anon;
select throws_ok($$select public.editorial_listar('materias')$$,'42501',null,'anônimo não lê redação');
select is((public.conteudo_publico('lista')->>'total')::int,0,'rascunhos ausentes do público');
select throws_ok($$select public.inscrever_newsletter('{}',repeat('a',64))$$,'42501',null,'inscrição não contorna gateway público');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.editorial_listar('newsletter')$$,'P0001','Acesso editorial negado','comercial não lê inscritos');
select throws_ok($$select public.editorial_salvar('categoria',null,'{"nome":"Categoria intrusa"}')$$,'P0001','Acesso editorial negado','comercial não cria categoria');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'mensal')::int,1,'Premium em teste recebe uma matéria mensal');
select set_config('test.mid',(public.salvar_materia(null,current_setting('test.sid')::uuid,current_setting('test.payload')::jsonb)->>'id'),true);
select is((select status from public.materias where id=current_setting('test.mid')::uuid),'rascunho','salvar cria rascunho privado');
select throws_ok($$select public.salvar_materia(current_setting('test.mid')::uuid,current_setting('test.sid')::uuid,current_setting('test.payload')::jsonb,99)$$,'P0001','A matéria mudou. Recarregue antes de salvar','edição concorrente protegida por versão');
select throws_ok($$select public.acao_materia(current_setting('test.mid')::uuid,'publicar')$$,'P0001','Acesso editorial negado','fornecedor não se publica');
select lives_ok($$select public.acao_materia(current_setting('test.mid')::uuid,'enviar')$$,'fornecedor envia para revisão');
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'mensal')::int,0,'envio reserva saldo mensal');
select set_config('test.second',(public.salvar_materia(null,current_setting('test.sid')::uuid,current_setting('test.payload')::jsonb)->>'id'),true);
select throws_ok($$select public.acao_materia(current_setting('test.second')::uuid,'enviar')$$,'P0001','Saldo de matérias insuficiente neste mês','envio extra bloqueado');
select throws_ok($$select public.salvar_materia(current_setting('test.mid')::uuid,current_setting('test.sid')::uuid,current_setting('test.payload')::jsonb,2)$$,'P0001','Sem permissão para editar esta matéria','envio em revisão não pode mudar');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.materias),0::bigint,'outra conta não vê rascunhos e revisão');
select throws_ok($$select public.saldo_materias(current_setting('test.sid')::uuid)$$,'P0001','Acesso negado','outra conta não vê saldo editorial');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select is((public.editorial_listar('materias')->>'total')::int,2,'editor lista contribuições privadas');
select throws_ok($$select public.acao_materia(current_setting('test.mid')::uuid,'ajuste','{"motivo":"curto"}')$$,'P0001','Revisão exige motivo de 10 a 2000 caracteres','comentário curto recusado');
select lives_ok($$select public.acao_materia(current_setting('test.mid')::uuid,'ajuste','{"motivo":"Detalhe melhor as orientações para os responsáveis."}')$$,'editor pede ajuste com motivo');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.acao_materia(current_setting('test.mid')::uuid,'enviar')$$,'reenvio após ajuste permitido');
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'usadas')::int,1,'reenvio da mesma matéria não reserva novamente');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.acao_materia(current_setting('test.mid')::uuid,'publicar')$$,'editor publica fornecedor após revisão');
reset role;
select set_config('test.slug',(select slug from public.materias where id=current_setting('test.mid')::uuid),true);
set local role anon;
select is(public.conteudo_publico('materia',current_setting('test.slug'))->'item'->>'selo','Conteúdo de marca','publicação recebe selo correto');
select is(public.conteudo_publico('materia',current_setting('test.slug'))->'item'->'fornecedor'->>'slug','empresa-editorial','publicação tem cartão do fornecedor');
select ok(not (public.conteudo_publico('materia',current_setting('test.slug'))->'item' ? 'motivo'),'projeção pública não expõe comentário privado');
reset role;
update public.fornecedores set status='suspenso' where id=current_setting('test.sid')::uuid;
select is(public.conteudo_publico('materia',current_setting('test.slug'))->'item','null'::jsonb,'suspensão do fornecedor retira matéria pública');
update public.fornecedores set status='publicado' where id=current_setting('test.sid')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select set_config('test.editor',(public.salvar_materia(null,null,current_setting('test.payload')::jsonb)->>'id'),true);
select lives_ok($$select public.acao_materia(current_setting('test.editor')::uuid,'agendar',jsonb_build_object('agendada_em',now()+interval '1 hour'))$$,'editor agenda matéria');
reset role;
select is((public.conteudo_publico('lista')->>'total')::int,1,'agendada não aparece antes da hora');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.publicar_agendadas(),0,'rotina não antecipa horário');
reset role;
update public.materias set agendada_em=now()-interval '1 minute' where id=current_setting('test.editor')::uuid;
set local role service_role;
select is(public.publicar_agendadas(),1,'publica quando chega o horário');
select is(public.publicar_agendadas(),0,'agendamento repetido não republica');
reset role;
select is((public.conteudo_publico('lista')->>'total')::int,2,'matéria agendada tornou-se pública');
select ok(exists(select 1 from public.audit_log where tabela='materias' and acao='UPDATE'),'mudanças editoriais auditadas');
select throws_ok($$select private.validate_article(current_setting('test.payload')::jsonb||jsonb_build_object('corpo',jsonb_build_array(jsonb_build_object('tipo','paragrafo','texto',repeat('palavra ',601)))),true)$$,'P0001','Limite do fornecedor: 600 palavras, um link e cinco fotos incluindo a capa','limite de palavras no servidor');
select throws_ok($$select private.validate_article(current_setting('test.payload')::jsonb||'{"corpo":[{"tipo":"paragrafo","texto":"Este texto contém dez palavras para testar a publicação sem invasões perigosas <script>"}]}'::jsonb,true)$$,'P0001','Não use HTML nos textos','HTML rejeitado no servidor');
set local role service_role;
select lives_ok($$select public.inscrever_newsletter('{"nome":"Leitor Exemplo","email":"leitor@test.example","perfil":"sindico","aceite":true}',repeat('a',64))$$,'newsletter registra pedido de inscrição');
reset role;
select is((select confirmado from public.newsletter_inscritos),false,'pedido inicial ainda não está confirmado');
select set_config('test.token',(select payload->>'token' from public.email_outbox where template='newsletter_confirmar'),true);
select ok((select token_confirmacao_hash<>current_setting('test.token') from public.newsletter_inscritos),'banco guarda hash do token');
set local role anon;
select is(public.newsletter_token(repeat('b',64),'confirmar')->>'valido','false','token incorreto não confirma');
select is(public.newsletter_token(current_setting('test.token'),'confirmar')->>'valido','true','link confirma segundo aceite');
select is(public.newsletter_token(current_setting('test.token'),'confirmar')->>'valido','false','token de confirmação tem uso único');
select throws_ok($$select email from public.newsletter_inscritos$$,'42501',null,'anônimo não acessa lista de e-mails');
reset role;
select ok((select confirmado from public.newsletter_inscritos),'confirmado ativo após segundo aceite');
select is((select count(*) from public.consentimentos where documento='newsletter' and origem='duplo_aceite'),1::bigint,'segundo aceite registrado');
select set_config('test.unsubscribe',(select payload->>'token' from public.email_outbox where template='newsletter_confirmada'),true);
set local role anon;
select is(public.newsletter_token(current_setting('test.unsubscribe'),'descadastrar')->>'valido','true','descadastro por link');
select is(public.newsletter_token(current_setting('test.unsubscribe'),'descadastrar')->>'valido','true','descadastro idempotente');
reset role;
select ok((select not confirmado and descadastrado_em is not null from public.newsletter_inscritos),'descadastrado não participa da lista ativa');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select ok(not (public.editorial_listar('newsletter')->'items'->0 ? 'token_confirmacao_hash'),'lista editorial não expõe tokens');
select throws_ok($$select token_confirmacao_hash from public.newsletter_inscritos$$,'42501',null,'editor não acessa hashes diretamente');
reset role;

set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select set_config('test.portal',public.editorial_salvar('portal',null,'{"nome":"Portal de Teste","url":"https://parceiro.example","vagas_por_mes":1,"ativo":true}')::text,true);
select lives_ok($$select public.editorial_salvar('categoria',null,'{"nome":"Categoria de Teste","ativa":true}')$$,'editor cria categoria');
select lives_ok($$select public.editorial_salvar('pauta',null,'{"titulo":"Pauta de Teste","status":"escrevendo"}')$$,'editor organiza pauta');
reset role;
update public.assinaturas set plano='destaque',status='ativa',periodo_ate=now()+interval '30 days' where fornecedor_id=current_setting('test.sid')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select set_config('test.partner_mid',public.salvar_materia(null,current_setting('test.sid')::uuid,current_setting('test.payload')::jsonb||jsonb_build_object('portal_id',current_setting('test.portal')))->>'id',true);
select lives_ok($$select public.acao_materia(current_setting('test.partner_mid')::uuid,'enviar')$$,'Destaque reserva blog e portal parceiro');
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'parceiro')::int,0,'vaga do fornecedor no parceiro foi consumida');
reset role;
insert into public.cortesias_materia(fornecedor_id) values(current_setting('test.sid')::uuid) on conflict do nothing;
set local role authenticated;
select lives_ok($$select public.acao_materia(current_setting('test.second')::uuid,'enviar')$$,'cortesia permite envio após franquia mensal');
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'cortesia')::int,0,'cortesia consumida uma vez');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.acao_materia(current_setting('test.partner_mid')::uuid,'publicar')$$,'editor aprova matéria com destino parceiro');
select set_config('test.partner_slug',(select slug from public.materias where id=current_setting('test.partner_mid')::uuid),true);
select throws_ok($$select public.editorial_salvar('entrega',null,jsonb_build_object('materia_id',current_setting('test.partner_mid'),'url_externa','https://outro.example/entrega','canonical_url','https://patri.example/materia/'||current_setting('test.partner_slug')))$$,'P0001','A entrega deve usar o domínio/caminho do portal reservado','entrega no domínio errado recusada');
select lives_ok($$select public.editorial_salvar('entrega',null,jsonb_build_object('materia_id',current_setting('test.partner_mid'),'url_externa','https://parceiro.example/entrega','canonical_url','https://patri.example/materia/'||current_setting('test.partner_slug')))$$,'entrega com canonical original registrada');
reset role;
insert into auth.users(id,email,raw_user_meta_data) values('70000000-0000-4000-8000-000000000004','content-partner-other@test.example','{"nome":"Outro Parceiro","tipo":"fornecedor","empresa":"Empresa Parceira Dois","cnpj":"04252011000110","telefone":"11999999999","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}');
select set_config('test.other_sid',(select id::text from public.fornecedores where dono_id='70000000-0000-4000-8000-000000000004'),true);
update public.fornecedores set status='publicado',slug='empresa-parceira-dois' where id=current_setting('test.other_sid')::uuid;
insert into public.assinaturas(fornecedor_id,plano,status,periodo_ate) values(current_setting('test.other_sid')::uuid,'destaque','ativa',now()+interval '30 days');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000004',true);
select set_config('test.other_mid',public.salvar_materia(null,current_setting('test.other_sid')::uuid,current_setting('test.payload')::jsonb||jsonb_build_object('portal_id',current_setting('test.portal')))->>'id',true);
select throws_ok($$select public.acao_materia(current_setting('test.other_mid')::uuid,'enviar')$$,'P0001','Sem vaga de portal parceiro neste mês','capacidade mensal do portal respeitada entre empresas');
reset role;
update public.materia_consumos set mes=(mes-interval '1 month')::date where fornecedor_id=current_setting('test.sid')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'mensal')::int,2,'franquia mensal nova não carrega consumo do mês anterior');
select is((public.saldo_materias(current_setting('test.sid')::uuid)->>'cortesia')::int,0,'cortesia já usada não renova no novo mês');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select lives_ok($$select public.inscrever_newsletter('{"nome":"Leitor Limite","email":"limite@test.example","perfil":"sindico","aceite":true}',repeat('c',64))$$,'primeira tentativa de newsletter registrada');
select public.inscrever_newsletter('{"nome":"Leitor Limite","email":"limite@test.example","perfil":"sindico","aceite":true}',repeat('c',64)) from generate_series(1,4);
select throws_ok($$select public.inscrever_newsletter('{"nome":"Leitor Limite","email":"limite@test.example","perfil":"sindico","aceite":true}',repeat('c',64))$$,'P0001','LIMITE_HORA','sexta tentativa por IP derivado bloqueada');
reset role;
select is((select count(*) from public.email_outbox where template='newsletter_confirmar' and destinatario='limite@test.example'),1::bigint,'cooldown do endereço não duplica confirmação');
update public.newsletter_inscritos set expira_em=now()-interval '1 second' where email='limite@test.example';
set local role anon;
select is(public.newsletter_token((select current_setting('test.token')),'confirmar')->>'valido','false','confirmação anterior continua inválida após uso');
reset role;
select * from finish();rollback;
